/* Wire messages between dlby processes (DESIGN.md §1, docs/architecture.svg).
 *
 * Senders must zero-initialize every message (memset to 0) before filling it in,
 * so pad bytes are never uninitialized: messages go over IPC and into the store
 * log byte-for-byte, and valgrind flags uninitialized bytes passed to send().
 *
 * Every message starts with `u8 type` at offset 0 and `u32 seq` (per sender) at
 * offset 4, so a receiver can read the type before it knows which struct it has.
 * All but the heartbeat carry origin_ns (CLOCK_MONOTONIC) at offset 8. Sizes are
 * fixed and checked below; a receiver validates type against length with
 * ipc_check_msg(). Fields are naturally aligned with explicit padding.
 */
#ifndef DLBY_MSG_H
#define DLBY_MSG_H

#include <assert.h>
#include <stddef.h>
#include <stdint.h>
#include <time.h>

enum msg_type {
	MSG_RADAR = 1,
	MSG_SONAR = 2,
	MSG_ALERT = 3,
	MSG_HB    = 4,
	MSG_GAP   = 5,
};

/* Fusion states carried to `alert` (DESIGN.md §1). HUB_LOST is alert's own. */
enum fuse_state {
	ST_BLIND = 0,
	ST_CLEAR,
	ST_APPROACHING,
	ST_IN_ZONE,
	ST_DEG_CLEAR,
	ST_DEG_APPROACHING,
	ST_DEG_IN_ZONE,
};

#define LOST_RADAR 0x01u
#define LOST_SONAR 0x02u

/* Radar target. PROVISIONAL until the LD2451 frame format is checked (Gage). */
#define RADAR_MAX_TARGETS 6
struct radar_target {
	uint16_t range_cm;
	int16_t  speed_cms;	/* negative = approaching */
	int8_t   angle_deg;
	uint8_t  dir;
	uint16_t snr;
};

struct radar_msg {		/* cap-radar -> fuse-hub, 10 Hz */
	uint8_t  type;		/* MSG_RADAR */
	uint8_t  ntargets;
	uint8_t  pad[2];
	uint32_t seq;
	uint64_t origin_ns;	/* user-space read time */
	struct radar_target t[RADAR_MAX_TARGETS];
};

#define SONAR_NO_ECHO    0x01u	/* no echo inside 4.3 m */
#define SONAR_STUCK_HIGH 0x02u	/* echo high > 60 ms */

struct sonar_msg {		/* cap-sonar -> fuse-hub, 16 Hz */
	uint8_t  type;		/* MSG_SONAR */
	uint8_t  flags;
	uint8_t  pad[2];
	uint32_t seq;
	uint64_t origin_ns;	/* kernel timestamp of the rising echo edge */
	uint32_t echo_ns;	/* rising -> falling edge */
	uint32_t trigger_seq;
};

struct alert_msg {		/* fuse-hub -> alert, on change + 2 Hz */
	uint8_t  type;		/* MSG_ALERT */
	uint8_t  state;		/* enum fuse_state */
	uint8_t  lost_mask;	/* LOST_* */
	uint8_t  pad;
	uint32_t seq;
	uint64_t origin_ns;	/* origin of the reading that caused this state */
};

struct gap_msg {		/* fuse-hub -> store, on reconnect after drops */
	uint8_t  type;		/* MSG_GAP */
	uint8_t  pad[3];
	uint32_t seq;
	uint64_t origin_ns;	/* when the link came back */
	uint32_t dropped;	/* records dropped while store was away */
	uint32_t pad2;
};

/* Heartbeats only travel on dlby-super's per-child socketpairs. */
struct hb_msg {
	uint8_t  type;		/* MSG_HB */
	uint8_t  pad[3];
	uint32_t seq;
};

#define MSG_MAX 64

static_assert(sizeof(struct radar_target) == 8, "radar_target size");
static_assert(sizeof(struct radar_msg) == 64, "radar_msg size");
static_assert(sizeof(struct sonar_msg) == 24, "sonar_msg size");
static_assert(sizeof(struct alert_msg) == 16, "alert_msg size");
static_assert(sizeof(struct hb_msg) == 8, "hb_msg size");
static_assert(sizeof(struct gap_msg) == 24, "gap_msg size");
static_assert(offsetof(struct radar_msg, seq) == 4 && offsetof(struct radar_msg, origin_ns) == 8,
	      "radar_msg header");
static_assert(offsetof(struct sonar_msg, seq) == 4 && offsetof(struct sonar_msg, origin_ns) == 8,
	      "sonar_msg header");
static_assert(offsetof(struct alert_msg, seq) == 4 && offsetof(struct alert_msg, origin_ns) == 8,
	      "alert_msg header");
static_assert(offsetof(struct gap_msg, seq) == 4 && offsetof(struct gap_msg, origin_ns) == 8,
	      "gap_msg header");
static_assert(offsetof(struct hb_msg, seq) == 4, "hb_msg header");

/* Expected length for a message type, or 0 if the type is unknown. */
static inline size_t msg_size(uint8_t type)
{
	switch (type) {
	case MSG_RADAR: return sizeof(struct radar_msg);
	case MSG_SONAR: return sizeof(struct sonar_msg);
	case MSG_ALERT: return sizeof(struct alert_msg);
	case MSG_HB:    return sizeof(struct hb_msg);
	case MSG_GAP:   return sizeof(struct gap_msg);
	default:        return 0;
	}
}

/* CLOCK_MONOTONIC in ns, or -1 with errno set. */
static inline int64_t dlby_now_ns(void)
{
	struct timespec ts;

	if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0)
		return -1;
	return (int64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

#endif

// Bench test for the LD2451 radar and HC-SR04 ultrasonic on an ESP32 DevKit.
// Test tool only -- not product code. The product runs on the Pi 5.
//
// Wiring (ESP32 on USB power). Board silkscreen label first, GPIO in parens;
// Dn == GPIOn, and GPIO16/17 are usually printed RX2/TX2.
//   LD2451  VCC -> VIN (5V; confirm against datasheet)   GND -> GND
//   LD2451  TX  -> RX2 (GPIO16)                          RX  -> TX2 (GPIO17)
//   HC-SR04 VCC -> VIN (5V)                              GND -> GND
//   HC-SR04 TRIG -> D18
//   HC-SR04 ECHO -> 1k -> D19, and 2k from D19 to GND (5V -> ~3.3V)
//   LED1 radar link   D25 -> 220-330R -> LED -> GND
//   LED2 radar target D26 -> 220-330R -> LED -> GND
//   LED3 sonar near   D27 -> 220-330R -> LED -> GND
//
// Serial monitor: 115200. Output lines:
//   RADAR <ms> <len> <hex bytes of whole frame>
//   SONAR <ms> <cm> | SONAR <ms> timeout

#define LOG_BAUD        115200
#define RADAR_BAUD      115200   // presumed LD2451 default
#define RADAR_RX_PIN    16
#define RADAR_TX_PIN    17
#define SONAR_TRIG_PIN  18
#define SONAR_ECHO_PIN  19
#define LED_LINK_PIN    25
#define LED_TARGET_PIN  26
#define LED_NEAR_PIN    27

#define FRAME_MAX       128      // header(4) + len(2) + payload + tail(4)
// UNVERIFIED: index of the target-count byte within the whole frame.
// Confirm against the datasheet and the raw RADAR dumps before trusting LED2.
#define TARGET_COUNT_OFFSET 6

#define RADAR_SILENT_MS 2000
#define LINK_BLINK_MS   50
#define SONAR_PERIOD_MS 60
#define SONAR_TIMEOUT_US 30000UL
#define NEAR_CM         100

static const uint8_t HDR[4]  = {0xF4, 0xF3, 0xF2, 0xF1};
static const uint8_t TAIL[4] = {0xF8, 0xF7, 0xF6, 0xF5};

static uint8_t frame[FRAME_MAX];
static size_t frame_n;
static size_t frame_len;          // payload length from the frame's length field
static uint32_t bad_frames;

static unsigned long last_radar_byte_ms;
static unsigned long last_radar_frame_ms;
static unsigned long last_warn_ms;
static unsigned long link_on_ms;
static unsigned long last_sonar_ms;

static void handle_frame(void)
{
	unsigned long now = millis();
	size_t total = 10 + frame_len;

	Serial.printf("RADAR %lu %u", now, (unsigned)frame_len);
	for (size_t i = 0; i < total; i++)
		Serial.printf(" %02X", frame[i]);
	Serial.print('\n');

	last_radar_frame_ms = now;
	link_on_ms = now;
	digitalWrite(LED_LINK_PIN, HIGH);

	// Offset must land inside the payload, not the tail; an empty
	// (len 0) frame means no targets.
	if (6 + frame_len > TARGET_COUNT_OFFSET)
		digitalWrite(LED_TARGET_PIN, frame[TARGET_COUNT_OFFSET] > 0 ? HIGH : LOW);
	else
		digitalWrite(LED_TARGET_PIN, LOW);
}

// Byte-at-a-time frame sync: match header, read length, wait for tail.
static void radar_feed(uint8_t b)
{
	if (frame_n < 4) {
		if (b == HDR[frame_n]) {
			frame[frame_n++] = b;
		} else if (b == HDR[0]) {
			frame[0] = b;
			frame_n = 1;
		} else {
			frame_n = 0;
		}
		return;
	}

	frame[frame_n++] = b;

	if (frame_n == 6) {
		frame_len = (size_t)frame[4] | ((size_t)frame[5] << 8);
		if (10 + frame_len > FRAME_MAX) {
			bad_frames++;
			Serial.printf("RADAR bad length %u (bad=%lu)\n",
				      (unsigned)frame_len, (unsigned long)bad_frames);
			frame_n = 0;
		}
		return;
	}

	if (frame_n > 6 && frame_n == 10 + frame_len) {
		if (memcmp(&frame[6 + frame_len], TAIL, sizeof(TAIL)) == 0) {
			handle_frame();
		} else {
			bad_frames++;
			Serial.printf("RADAR bad tail (bad=%lu)\n", (unsigned long)bad_frames);
		}
		frame_n = 0;
	}
}

static void radar_poll(void)
{
	while (Serial2.available() > 0) {
		int c = Serial2.read();
		if (c < 0)
			break;
		last_radar_byte_ms = millis();
		radar_feed((uint8_t)c);
	}
}

static void sonar_measure(void)
{
	digitalWrite(SONAR_TRIG_PIN, LOW);
	delayMicroseconds(2);
	digitalWrite(SONAR_TRIG_PIN, HIGH);
	delayMicroseconds(10);
	digitalWrite(SONAR_TRIG_PIN, LOW);

	unsigned long us = pulseIn(SONAR_ECHO_PIN, HIGH, SONAR_TIMEOUT_US);
	unsigned long now = millis();

	if (us == 0) {
		Serial.printf("SONAR %lu timeout\n", now);
		digitalWrite(LED_NEAR_PIN, LOW);
		return;
	}

	unsigned long cm = us / 58;
	Serial.printf("SONAR %lu %lu\n", now, cm);
	digitalWrite(LED_NEAR_PIN, cm < NEAR_CM ? HIGH : LOW);
}

void setup()
{
	Serial.begin(LOG_BAUD);

	pinMode(LED_LINK_PIN, OUTPUT);
	pinMode(LED_TARGET_PIN, OUTPUT);
	pinMode(LED_NEAR_PIN, OUTPUT);
	pinMode(SONAR_TRIG_PIN, OUTPUT);
	pinMode(SONAR_ECHO_PIN, INPUT);
	digitalWrite(SONAR_TRIG_PIN, LOW);

	// Room for ~90ms of radar bytes while pulseIn blocks.
	Serial2.setRxBufferSize(1024);
	Serial2.begin(RADAR_BAUD, SERIAL_8N1, RADAR_RX_PIN, RADAR_TX_PIN);

	Serial.println("bench: LD2451 + HC-SR04 start");
}

void loop()
{
	unsigned long now = millis();

	radar_poll();

	if (now - link_on_ms >= LINK_BLINK_MS)
		digitalWrite(LED_LINK_PIN, LOW);

	if (now - last_radar_frame_ms >= RADAR_SILENT_MS)
		digitalWrite(LED_TARGET_PIN, LOW);

	if (now - last_radar_byte_ms >= RADAR_SILENT_MS &&
	    now - last_warn_ms >= RADAR_SILENT_MS) {
		Serial.println("RADAR no data: check 5V power, TX/RX swap, baud");
		last_warn_ms = now;
	}

	if (now - last_sonar_ms >= SONAR_PERIOD_MS) {
		last_sonar_ms = now;
		sonar_measure();
		radar_poll();
	}
}

