1	/* Wire messages between dlby processes (DESIGN.md §1, docs/architecture.svg).
2	 *
3	 * Senders must zero-initialize every message (memset to 0) before filling it in,
4	 * so pad bytes are never uninitialized: messages go over IPC and into the store
5	 * log byte-for-byte, and valgrind flags uninitialized bytes passed to send().
6	 *
7	 * Every message starts with `u8 type` at offset 0 and `u32 seq` (per sender) at
8	 * offset 4, so a receiver can read the type before it knows which struct it has.
9	 * All but the heartbeat carry origin_ns (CLOCK_MONOTONIC) at offset 8. Sizes are
10	 * fixed and checked below; a receiver validates type against length with
11	 * ipc_check_msg(). Fields are naturally aligned with explicit padding.
12	 */
13	#ifndef DLBY_MSG_H
14	#define DLBY_MSG_H
15	
16	#include <assert.h>
17	#include <stddef.h>
18	#include <stdint.h>
19	#include <time.h>
20	
21	enum msg_type {
22		MSG_RADAR = 1,
23		MSG_SONAR = 2,
24		MSG_ALERT = 3,
25		MSG_HB    = 4,
26		MSG_GAP   = 5,
27	};
28	
29	/* Fusion states carried to `alert` (DESIGN.md §1). HUB_LOST is alert's own. */
30	enum fuse_state {
31		ST_BLIND = 0,
32		ST_CLEAR,
33		ST_APPROACHING,
34		ST_IN_ZONE,
35		ST_DEG_CLEAR,
36		ST_DEG_APPROACHING,
37		ST_DEG_IN_ZONE,
38	};
39	
40	#define LOST_RADAR 0x01u
41	#define LOST_SONAR 0x02u
42	
43	/* Radar target. PROVISIONAL until the LD2451 frame format is checked (Gage). */
44	#define RADAR_MAX_TARGETS 6
45	struct radar_target {
46		uint16_t range_cm;
47		int16_t  speed_cms;	/* negative = approaching */
48		int8_t   angle_deg;
49		uint8_t  dir;
50		uint16_t snr;
51	};
52	
53	struct radar_msg {		/* cap-radar -> fuse-hub, 10 Hz */
54		uint8_t  type;		/* MSG_RADAR */
55		uint8_t  ntargets;
56		uint8_t  pad[2];
57		uint32_t seq;
58		uint64_t origin_ns;	/* user-space read time */
59		struct radar_target t[RADAR_MAX_TARGETS];
60	};
61	
62	#define SONAR_NO_ECHO    0x01u	/* no echo inside 4.3 m */
63	#define SONAR_STUCK_HIGH 0x02u	/* echo high > 60 ms */
64	
65	struct sonar_msg {		/* cap-sonar -> fuse-hub, 16 Hz */
66		uint8_t  type;		/* MSG_SONAR */
67		uint8_t  flags;
68		uint8_t  pad[2];
69		uint32_t seq;
70		uint64_t origin_ns;	/* kernel timestamp of the rising echo edge */
71		uint32_t echo_ns;	/* rising -> falling edge */
72		uint32_t trigger_seq;
73	};
74	
75	struct alert_msg {		/* fuse-hub -> alert, on change + 2 Hz */
76		uint8_t  type;		/* MSG_ALERT */
77		uint8_t  state;		/* enum fuse_state */
78		uint8_t  lost_mask;	/* LOST_* */
79		uint8_t  pad;
80		uint32_t seq;
81		uint64_t origin_ns;	/* origin of the reading that caused this state */
82	};
83	
84	struct gap_msg {		/* fuse-hub -> store, on reconnect after drops */
85		uint8_t  type;		/* MSG_GAP */
86		uint8_t  pad[3];
87		uint32_t seq;
88		uint64_t origin_ns;	/* when the link came back */
89		uint32_t dropped;	/* records dropped while store was away */
90		uint32_t pad2;
91	};
92	
93	/* Heartbeats only travel on dlby-super's per-child socketpairs. */
94	struct hb_msg {
95		uint8_t  type;		/* MSG_HB */
96		uint8_t  pad[3];
97		uint32_t seq;
98	};
99	
100	#define MSG_MAX 64
101	
102	static_assert(sizeof(struct radar_target) == 8, "radar_target size");
103	static_assert(sizeof(struct radar_msg) == 64, "radar_msg size");
104	static_assert(sizeof(struct sonar_msg) == 24, "sonar_msg size");
105	static_assert(sizeof(struct alert_msg) == 16, "alert_msg size");
106	static_assert(sizeof(struct hb_msg) == 8, "hb_msg size");
107	static_assert(sizeof(struct gap_msg) == 24, "gap_msg size");
108	static_assert(offsetof(struct radar_msg, seq) == 4 && offsetof(struct radar_msg, origin_ns) == 8,
109		      "radar_msg header");
110	static_assert(offsetof(struct sonar_msg, seq) == 4 && offsetof(struct sonar_msg, origin_ns) == 8,
111		      "sonar_msg header");
112	static_assert(offsetof(struct alert_msg, seq) == 4 && offsetof(struct alert_msg, origin_ns) == 8,
113		      "alert_msg header");
114	static_assert(offsetof(struct gap_msg, seq) == 4 && offsetof(struct gap_msg, origin_ns) == 8,
115		      "gap_msg header");
116	static_assert(offsetof(struct hb_msg, seq) == 4, "hb_msg header");
117	
118	/* Expected length for a message type, or 0 if the type is unknown. */
119	static inline size_t msg_size(uint8_t type)
120	{
121		switch (type) {
122		case MSG_RADAR: return sizeof(struct radar_msg);
123		case MSG_SONAR: return sizeof(struct sonar_msg);
124		case MSG_ALERT: return sizeof(struct alert_msg);
125		case MSG_HB:    return sizeof(struct hb_msg);
126		case MSG_GAP:   return sizeof(struct gap_msg);
127		default:        return 0;
128		}
129	}
130	
131	/* CLOCK_MONOTONIC in ns, or -1 with errno set. */
132	static inline int64_t dlby_now_ns(void)
133	{
134		struct timespec ts;
135	
136		if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0)
137			return -1;
138		return (int64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
139	}
140	
141	#endif
