void log_limited(struct log_limit *lim, int64_t now_ns, enum log_level lv, const char *fmt, ...)
{
	va_list ap;

	lim->count++;
	if (lim->primed && now_ns - lim->last_ns < LOG_LIMIT_NS)
		return;
	va_start(ap, fmt);
	emit(lv, lim->count, fmt, ap);
	va_end(ap);
	lim->count = 0;
	lim->last_ns = now_ns;
	lim->primed = true;
}
