			p->n = 0;
		return RADAR_MORE;
	}

	p->buf[p->n++] = b;
	if (p->n == 6) {
		p->len = (size_t)p->buf[4] | ((size_t)p->buf[5] << 8);
		if (p->len > RADAR_PAYLOAD_MAX) {
			p->n = 0;
			p->bad_len++;
			return RADAR_BAD_LEN;
		}
		return RADAR_MORE;
	}
	if (p->n < RADAR_FRAME_OVERHEAD + p->len)
		return RADAR_MORE;

	p->n = 0;
	if (memcmp(&p->buf[6 + p->len], TAIL, sizeof(TAIL)) != 0) {
		p->bad_tail++;
		return RADAR_BAD_TAIL;
	}
	p->frames++;
	return RADAR_FRAME;
}

/* Classifies one HC-SR04 ping for cap-sonar from the kernel-stamped edges seen
 * on ECHO after the trigger (DESIGN.md §2 C). Pure: no I/O, so it is unit-tested
 * directly.
 *
 *   ECHO_OK     rise then fall, width <= ECHO_MAX_NS: send echo_ns
 *   ECHO_FAR    rise then fall, wider: sensor alive, nothing inside 4.3 m
 *               (SONAR_NO_ECHO)
 *   ECHO_NONE   no rising edge and the line is low: sensor not answering
 *   ECHO_STUCK  still high at the end of the ping: stuck high (> 60 ms)
 *
 * fuse-hub counts any SONAR message as "alive", so cap-sonar sends nothing for
 * NONE and STUCK; the hub's 8-ping staleness then marks the sonar lost.
 */
#ifndef DLBY_ECHO_H
#define DLBY_ECHO_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define ECHO_MAX_NS 25000000LL	/* 2 * 4.3 m / 343 m/s */

enum echo_result {
	ECHO_OK,
	ECHO_FAR,
	ECHO_NONE,
	ECHO_STUCK,
};

struct echo_edge {
	int64_t ts_ns;		/* kernel timestamp, CLOCK_MONOTONIC */
	bool    rising;
};

struct echo_ping {
	int64_t  rise_ns;	/* valid for OK and FAR */
	uint32_t width_ns;	/* valid for OK and FAR */
};

/* e: the edges since the trigger, oldest first. high_now: ECHO's level at the
 * end of the ping. */
enum echo_result echo_classify(const struct echo_edge *e, size_t n, bool high_now,
			       struct echo_ping *out);

const char *echo_result_name(enum echo_result r);

#endif

#include "echo.h"

enum echo_result echo_classify(const struct echo_edge *e, size_t n, bool high_now,
			       struct echo_ping *out)
{
	int64_t width;
	size_t i, j;

	/* A leading falling edge is the tail of an earlier pulse: skip it. */
	for (i = 0; i < n && !e[i].rising; i++)
		;
	if (i == n)
		return high_now ? ECHO_STUCK : ECHO_NONE;
	for (j = i + 1; j < n && e[j].rising; j++)
		;
	if (j == n)
		return ECHO_STUCK;

	width = e[j].ts_ns - e[i].ts_ns;
	if (width < 0)
		width = 0;	/* not on one clock; never seen, but don't wrap */
	out->rise_ns = e[i].ts_ns;
	out->width_ns = width > ECHO_MAX_NS ? (uint32_t)ECHO_MAX_NS + 1 : (uint32_t)width;
	return width > ECHO_MAX_NS ? ECHO_FAR : ECHO_OK;
}

const char *echo_result_name(enum echo_result r)
{
	switch (r) {
	case ECHO_OK:    return "ok";
	case ECHO_FAR:   return "far";
	case ECHO_NONE:  return "no_echo";
	case ECHO_STUCK: return "stuck_high";
	}
	return "unknown";
}

