		log_msg(LOG_E, "open_failed dev=%s err=%s", dev, strerror(errno));
		rc = errno == ENOENT || errno == EACCES || errno == ENOTDIR ? EX_CONFIG : EX_UNAVAILABLE;
		goto out;
	}
