		pfd[1] = (struct pollfd){ .fd = tfd, .events = POLLIN };
		pfd[2] = (struct pollfd){ .fd = s.echo_fd, .events = POLLIN };
		pfd[3] = (struct pollfd){ .fd = hb.fd, .events = POLLIN };	/* -1: ignored */

		if (poll(pfd, 4, POLL_MS) < 0) {
