/* Feeds n bytes; returns how many frames completed, counting other results in *other. */
static int feed_all(struct radar_parser *p, const uint8_t *b, size_t n, int *other)
{
	int frames = 0;
	size_t i;

	for (i = 0; i < n; i++) {
